const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js'); 

// Create a new Discord client
const client = new Client({ intents: [GatewayIntentBits.Guilds, GatewayIntentBits.DirectMessages] }); 

// Define a function to handle the slash command
const slashCommands = new Map();

// Define the command
const banCommand = new SlashCommandBuilder()
   .setName('ban')
   .setDescription('Ban a user from the server.')
   .addUserOption(option => option.setName('user').setDescription('The user to ban').setRequired(true))
   .toJSON();

// Add the command to the map
slashCommands.set('ban', banCommand);

// Event listener for the interaction create event
client.on('interactionCreate', async interaction => {
    if (!interaction.isChatInputCommand()) return;

    const command = slashCommands.get(interaction.commandName);
    if (!command) return;

    try {
        await interaction.deferReply();
        switch (interaction.commandName) {
            case 'ban':
                const user = interaction.options.getUser('user');
                if (!user) {
                    await interaction.reply({ content: 'Please provide a user to ban.', ephemeral: true });
                    return;
                }
                const member = interaction.guild.members.cache.get(user.id);
                if (!member) {
                    await interaction.reply({ content: `User ${user.tag} is not in this server.`, ephemeral: true });
                    return;
                }
                if (interaction.user.id === user.id) {
                    await interaction.reply({ content: 'You cannot ban yourself.', ephemeral: true });
                    return;
                }
                if (!interaction.member.permissions.has('BAN_MEMBERS')) {
                    await interaction.reply({ content: 'You do not have permission to ban members.', ephemeral: true });
                    return;
                }
                await interaction.guild.members.ban(user, { reason: 'Ban reason' });
                await interaction.reply({ content: `User ${user.tag} has been banned.`, ephemeral: false });
                break;
        }
    } catch (error) {
        console.error(error);
        await interaction.reply({ content: 'An error occurred while processing your request.', ephemeral: true });
    }
});

